@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&display=swap');
:root{--ink:#f3f5f0;--muted:#a8b7b9;--mint:#a7f3d0;--orange:#ffbd75;--panel:rgba(12,24,29,.82);--line:rgba(209,237,226,.14)}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#101a20;color:var(--ink);font-family:Manrope,system-ui,sans-serif;touch-action:none}.game-shell{position:relative;width:100%;height:100%;min-height:320px;overflow:hidden;background:#253938}canvas#game{position:absolute;width:100%;height:100%;inset:0;display:block}.vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(8,18,23,.66),transparent 21%,transparent 71%,rgba(8,18,23,.52)),radial-gradient(ellipse at center,transparent 45%,rgba(5,13,16,.22) 100%)}.topbar{position:absolute;z-index:2;left:30px;right:30px;top:24px;display:flex;align-items:center;justify-content:space-between;pointer-events:none}.brand,.district-tag,.icon-btn{pointer-events:auto}.brand{display:flex;align-items:center;gap:11px;text-shadow:0 2px 12px #071218}.brand-mark{width:37px;height:37px;border:1px solid rgba(167,243,208,.72);border-radius:11px;display:grid;place-items:center;color:var(--mint);font-size:12px;font-weight:800;letter-spacing:-.7px;background:rgba(13,36,37,.62)}.brand b{font-size:12px;letter-spacing:2.1px;display:block}.brand small{font:9px 'DM Mono',monospace;color:#b8c5c2;letter-spacing:1.6px}.district-tag{position:absolute;left:50%;transform:translateX(-50%);font:10px 'DM Mono',monospace;letter-spacing:1.5px;color:#e3e8df;background:rgba(10,25,28,.58);padding:10px 14px;border:1px solid var(--line);border-radius:3px;white-space:nowrap;backdrop-filter:blur(8px)}.district-tag i{display:inline-block;width:6px;height:6px;border-radius:50%;background:#a7f3d0;margin-right:8px;box-shadow:0 0 10px #a7f3d0}.icon-btn{background:rgba(10,25,28,.58);border:1px solid var(--line);color:white;width:38px;height:38px;border-radius:50%;font-size:22px;cursor:pointer}.hud-left{position:absolute;left:30px;top:99px;width:240px;display:grid;gap:10px}.status-card,.objective-card,.wanted-card{background:var(--panel);border:1px solid var(--line);backdrop-filter:blur(10px);box-shadow:0 12px 35px #0a161750}.status-card{padding:13px 15px;border-radius:4px}.status-title{display:flex;justify-content:space-between;align-items:center;font:9px 'DM Mono',monospace;letter-spacing:1.35px;color:#aab8b5}.status-title b{font:11px 'DM Mono',monospace;color:#e8f3ec;letter-spacing:.3px}.meter{height:4px;background:#344543;margin:8px 0 12px;overflow:hidden}.meter i{height:100%;width:100%;display:block;background:linear-gradient(90deg,#69d9a5,#c6f7ce);transition:width .25s}.cash-line b{color:var(--mint)}.objective-card{padding:14px 15px 12px;border-radius:4px;position:relative;overflow:hidden}.objective-card:before{content:'';position:absolute;left:0;top:0;bottom:0;width:2px;background:#f4bd75}.eyebrow{display:block;color:#9eb2ad;font:9px 'DM Mono',monospace;letter-spacing:1.6px}.objective-card>b{display:block;font-size:12px;margin-top:8px;font-weight:700}.objective-card p{font-size:10px;line-height:1.5;color:#adbfba;margin:5px 0 12px}.objective-reward{display:flex;justify-content:space-between;border-top:1px solid var(--line);padding-top:9px;font:9px 'DM Mono',monospace;color:#9eb2ad;letter-spacing:1px}.objective-reward b{color:#ffd096;font-size:11px}.hud-right{position:absolute;right:30px;top:99px;width:180px;display:grid;gap:10px}.wanted-card{padding:12px 14px;border-radius:4px}.stars{font-size:18px;letter-spacing:4px;color:#ffca76;margin:6px 0 2px;white-space:nowrap;text-shadow:0 0 9px #ffbd7560}.wanted-card small{font:9px 'DM Mono',monospace;color:#a9b8b2}.minimap-frame{position:relative;padding:5px;background:rgba(12,24,29,.82);border:1px solid var(--line);box-shadow:0 12px 35px #0a161750}.minimap-frame canvas{display:block;width:100%;height:auto}.map-label{position:absolute;bottom:10px;left:11px;font:8px 'DM Mono',monospace;letter-spacing:1.4px;color:#e7eee6;text-shadow:0 1px 5px #000}.bottom-hud{position:absolute;z-index:2;bottom:23px;left:30px;right:30px;display:flex;align-items:flex-end;justify-content:space-between;pointer-events:none}.controls-hint{display:flex;align-items:center;gap:7px;color:#d4dfd9;font:8px 'DM Mono',monospace;letter-spacing:1px;background:rgba(9,20,24,.55);border:1px solid var(--line);padding:9px 11px;backdrop-filter:blur(8px)}kbd{font:9px 'DM Mono',monospace;border:1px solid #71827d;border-bottom-width:2px;border-radius:3px;padding:3px 5px;color:#ecf4ee;min-width:20px;text-align:center}.clock{display:flex;align-items:center;gap:10px;background:rgba(9,20,24,.58);border:1px solid var(--line);padding:9px 12px;font:9px 'DM Mono',monospace;letter-spacing:1px;color:#c3d0ca}.clock b{font-size:12px;color:#fff}.sun-icon{font-size:14px;color:#ffd082}.toast{position:absolute;z-index:5;left:50%;top:20%;transform:translate(-50%,-10px);opacity:0;background:rgba(9,23,26,.9);border:1px solid rgba(167,243,208,.4);padding:11px 17px;color:#eafff3;font:10px 'DM Mono',monospace;letter-spacing:1px;transition:.3s;pointer-events:none;white-space:nowrap}.toast.show{opacity:1;transform:translate(-50%,0)}.intro{position:absolute;z-index:8;inset:0;display:grid;place-items:center;background:linear-gradient(90deg,rgba(5,15,18,.75),rgba(7,17,20,.17) 75%)}.intro-card{margin-left:-35%;width:min(420px,80vw);padding:32px 35px;background:linear-gradient(135deg,rgba(12,29,31,.91),rgba(11,24,27,.73));border:1px solid rgba(211,238,225,.2);box-shadow:0 25px 80px #0610129c;backdrop-filter:blur(8px)}.intro-kicker{font:10px 'DM Mono',monospace;letter-spacing:2.5px;color:#a8efca}.intro h1{font-size:clamp(38px,5vw,63px);line-height:.98;letter-spacing:-3px;margin:17px 0 15px;font-weight:700}.intro h1 em{font-style:normal;color:#f5c282}.intro-card p{font-size:13px;color:#bac9c2;line-height:1.7;max-width:330px}.intro-card button{margin-top:14px;width:100%;padding:14px 15px;text-align:left;background:#b8efcf;border:0;color:#102420;font:800 10px 'DM Mono',monospace;letter-spacing:1.2px;cursor:pointer}.intro-card button span{float:right;font-size:18px;line-height:10px}.intro-foot{font:8px 'DM Mono',monospace;color:#98aaa3;letter-spacing:.7px;margin-top:18px}.intro-foot i{color:#f3c07d;font-style:normal;margin:0 4px}.help-panel{position:absolute;z-index:9;right:30px;bottom:77px;width:min(320px,80vw);padding:18px;background:var(--panel);border:1px solid var(--line);font-size:11px;line-height:1.6;color:#c1d0c8;display:none}.help-panel.open{display:block}.help-panel>b{color:var(--mint);font:10px 'DM Mono',monospace;letter-spacing:1.7px}.help-panel p{margin:9px 0}.help-panel button{float:right;background:none;border:0;color:white;font-size:20px;cursor:pointer}.touch-controls{display:none;position:absolute;z-index:4;bottom:24px;left:20px;right:20px;justify-content:space-between;align-items:flex-end;pointer-events:none}.touch-controls button{pointer-events:auto;color:#fff;background:rgba(13,29,31,.64);border:1px solid rgba(220,241,225,.28);backdrop-filter:blur(6px);touch-action:none}.dpad{display:grid;justify-items:center;gap:4px}.dpad>div{display:flex;gap:4px}.dpad button{width:44px;height:40px;border-radius:8px;font-size:17px}.touch-actions{display:flex;gap:10px;align-items:flex-end}.touch-actions button{width:57px;height:57px;border-radius:50%;font:10px 'DM Mono',monospace;letter-spacing:1px}.touch-actions .action-btn{background:rgba(191,115,67,.77)}.touch-actions .enter-btn{width:69px;height:69px;background:rgba(56,131,102,.83)}
@media(max-width:700px){.topbar{left:15px;right:15px;top:14px}.brand-mark{width:32px;height:32px}.brand b{font-size:10px}.brand small{font-size:7px}.district-tag{top:43px;font-size:8px;padding:7px 10px}.hud-left{left:14px;top:90px;width:clamp(145px,39vw,210px);gap:7px}.status-card{padding:10px}.objective-card{padding:10px}.objective-card>b{font-size:10px}.objective-card p{font-size:9px;margin:4px 0 8px}.hud-right{right:13px;top:90px;width:clamp(95px,26vw,140px);gap:6px}.wanted-card{padding:9px}.stars{font-size:14px;letter-spacing:1px}.wanted-card small{font-size:7px}.minimap-frame{padding:3px}.map-label{font-size:6px;bottom:7px;left:7px}.bottom-hud{left:14px;right:14px;bottom:15px}.controls-hint{display:none}.clock{margin-left:auto;padding:7px 9px;font-size:8px}.touch-controls{display:flex}.intro-card{margin:0;width:min(420px,88vw);padding:26px}.intro h1{font-size:48px}.intro-card p{font-size:12px}.intro-foot{font-size:7px}.help-panel{right:14px;bottom:100px}.toast{top:28%}}
@media (pointer:coarse){.touch-controls{display:flex}.bottom-hud{bottom:15px}.controls-hint{display:none}}

(()=>{
'use strict';
const canvas=document.getElementById('game'),ctx=canvas.getContext('2d'),mini=document.getElementById('minimap'),mx=mini.getContext('2d');
const ui={health:document.getElementById('health-value'),healthBar:document.getElementById('health-bar'),cash:document.getElementById('cash'),district:document.getElementById('district'),stars:document.getElementById('stars'),wantedNote:document.getElementById('wanted-note'),clock:document.getElementById('clock'),weather:document.getElementById('weather'),weatherIcon:document.getElementById('weather-icon'),toast:document.getElementById('toast'),intro:document.getElementById('intro'),objective:document.getElementById('objective'),objectiveCopy:document.getElementById('objective-copy')};
const W=2400, CELL=300, ROAD=72, ISOX=.72, ISOY=.36;
let cw=innerWidth,ch=innerHeight,dpr=1,now=0,last=0,toastTimer=0,gameStarted=false,keys={},touch={};
function resize(){dpr=Math.min(devicePixelRatio||1,2);cw=innerWidth;ch=innerHeight;canvas.width=cw*dpr;canvas.height=ch*dpr;ctx.setTransform(dpr,0,0,dpr,0,0)}addEventListener('resize',resize);resize();
const rand=(x,y,n=0)=>{let v=Math.sin(x*127.1+y*311.7+n*74.7)*43758.5453;return v-Math.floor(v)};
function districtAt(x,y){if(x>1810&&y>1550)return'PALOMA BEACH';if(x<600&&y<650)return'OLD HARBOR';if(x>1700&&y<800)return'VEGA HEIGHTS';if(x<760&&y>1600)return'IRONWORKS';if(x>900&&x<1550&&y>900&&y<1570)return'MIRAGE DOWNTOWN';return'GARDEN DISTRICT'}
const player={x:1195,y:1255,vx:0,vy:0,angle:0,health:100,cash:2450,vehicle:null,walk:0,face:0};
let wanted=0,wantedHeat=0,day=16.7,shots=[],particles=[],messages=[],objective={x:1370,y:1090,active:true},cars=[],peds=[],buildings=[],trees=[],parks=[],lamps=[];
const carColors=['#d9b36f','#c77c61','#4c8f91','#838d8d','#bd5548','#dabd9a','#768b65','#454d5a'];
function isRoad(x,y){return x%CELL<ROAD||y%CELL<ROAD}
function blockBounds(x,y){return{x:Math.floor(x/CELL)*CELL+ROAD+9,y:Math.floor(y/CELL)*CELL+ROAD+9,w:CELL-ROAD-18,h:CELL-ROAD-18}}
function createCity(){
 for(let gy=0;gy<8;gy++)for(let gx=0;gx<8;gx++){
  const b=blockBounds(gx*CELL+ROAD,gy*CELL+ROAD),r=rand(gx,gy),district=districtAt(b.x,b.y);
  if(r<.14||((gx===3||gx===4)&&(gy===3||gy===4))){parks.push({...b,kind:r<.06?'plaza':'park',seed:gx*19+gy});for(let i=0;i<5;i++)trees.push({x:b.x+25+rand(gx,gy,i)*Math.max(1,b.w-50),y:b.y+25+rand(gy,gx,i+7)*Math.max(1,b.h-50),size:11+rand(gx,gy,i+13)*7});continue}
  const count=district==='MIRAGE DOWNTOWN'?3:1+Math.floor(rand(gx,gy,2)*2);
  for(let i=0;i<count;i++){let cols=count===1?1:2,rows=count===1?1:2,bw=(b.w-18)/cols,bh=(b.h-18)/rows,x=b.x+7+(i%cols)*bw,y=b.y+7+Math.floor(i/cols)*bh;let type=district==='MIRAGE DOWNTOWN'?'tower':district==='IRONWORKS'?'warehouse':rand(gx,gy,i+9)>.65?'shop':'building';buildings.push({x,y,w:bw-8,h:bh-8,height:type==='tower'?70+rand(gx,gy,i+21)*100:type==='warehouse'?23:24+rand(gx,gy,i+31)*26,type,color:district==='MIRAGE DOWNTOWN'?['#586b68','#66796f','#8a7966','#495c61'][Math.floor(rand(gx,gy,i+40)*4)]:['#987b62','#758477','#a88670','#667d78'][Math.floor(rand(gx,gy,i+40)*4)],seed:gx*31+gy*13+i})}
 }
 for(let i=0;i<26;i++){let x=160+rand(i,4)*2050,y=120+rand(i,8)*2160;if(!isRoad(x,y))cars.push({x,y,angle:Math.floor(rand(i,5)*4)*Math.PI/2,speed:0,max:45+rand(i,3)*25,color:carColors[i%carColors.length],type:i%9===0?'bike':i%7===0?'suv':'car',ai:true,wait:rand(i,9)*2,damage:0})}
 for(let i=0;i<48;i++){let x=150+rand(i,10)*2100,y=150+rand(i,12)*2100;if(isRoad(x,y))x+=96;if(isRoad(x,y))y+=96;peds.push({x,y,angle:rand(i,14)*Math.PI*2,speed:12+rand(i,18)*10,shirt:['#b8a47a','#698f82','#be785e','#7c8eaf','#dfc389'][i%5],phase:rand(i,25)*6,scared:0})}
 for(let x=0;x<W;x+=CELL)for(let y=0;y<W;y+=CELL){if(rand(x,y,33)>.58)lamps.push({x:x+ROAD-8,y:y+CELL*.53});if(rand(x,y,39)>.56)lamps.push({x:x+CELL*.53,y:y+ROAD-8})}
}
createCity();
function project(x,y){return{x:(x-y)*ISOX,y:(x+y)*ISOY}}
let cam={x:player.x,y:player.y};
function screen(x,y,z=0){let a=project(x-cam.x,y-cam.y);return{x:cw/2+a.x,y:ch/2+a.y-z}}
function poly(points,fill,stroke=null,width=1){ctx.beginPath();points.forEach((p,i)=>{i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y)});ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=width;ctx.stroke()}}
function ellipse(x,y,rx,ry,color){ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.fillStyle=color;ctx.fill()}
function ground(){
 const corners=[[0,0],[W,0],[W,W],[0,W]].map(([x,y])=>screen(x,y));poly(corners,'#557864');
 // District ground variation and beaches
 for(let gx=0;gx<8;gx++)for(let gy=0;gy<8;gy++){let x=gx*CELL,y=gy*CELL,b=blockBounds(x+ROAD,y+ROAD),park=parks.find(p=>p.x===b.x&&p.y===b.y);let col=park?'#628365':districtAt(b.x,b.y)==='PALOMA BEACH'?'#d2b780':'#708b70';let pts=[[b.x,b.y],[b.x+b.w,b.y],[b.x+b.w,b.y+b.h],[b.x,b.y+b.h]].map(p=>screen(...p));poly(pts,col);if(park){poly([[b.x+8,b.y+8],[b.x+b.w-8,b.y+8],[b.x+b.w-8,b.y+b.h-8],[b.x+8,b.y+b.h-8]].map(p=>screen(...p)),park.kind==='plaza'?'#9b9d82':'#73936f')}}
 // coastal water edge
 let coast=[[1900,0],[W,0],[W,W],[2210,W],[2140,1900],[2040,1760],[1970,1400]].map(p=>screen(...p));poly(coast,'#467d85');
 // Road grid, drawn as isometric world strips
 for(let k=0;k<=W;k+=CELL){let a=screen(k,0),b=screen(k,W),c=screen(k+ROAD,0),d=screen(k+ROAD,W);poly([a,b,d,c],'#4b5150');let aa=screen(0,k),bb=screen(W,k),cc=screen(0,k+ROAD),dd=screen(W,k+ROAD);poly([aa,bb,dd,cc],'#4b5150')}
 // lanes in dashed segments
 ctx.save();ctx.setLineDash([12,12]);ctx.lineWidth=1;ctx.strokeStyle='rgba(233,209,151,.55)';for(let k=ROAD/2;k<W;k+=CELL){let a=screen(k,0),b=screen(k,W);ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke();let c=screen(0,k),d=screen(W,k);ctx.beginPath();ctx.moveTo(c.x,c.y);ctx.lineTo(d.x,d.y);ctx.stroke()}ctx.restore();
 // Crosswalk markings at intersections
 for(let x=0;x<W;x+=CELL)for(let y=0;y<W;y+=CELL){if(x===0||y===0)continue;for(let i=0;i<4;i++){let p=screen(x+12+i*11,y+ROAD-10);poly([{x:p.x-3,y:p.y-2},{x:p.x+4,y:p.y+1},{x:p.x+4,y:p.y+7},{x:p.x-3,y:p.y+4}],'rgba(232,230,207,.53)')}}
}
function drawParks(){for(const p of parks){const a=screen(p.x,p.y);ctx.strokeStyle='rgba(224,220,181,.35)';ctx.lineWidth=2;ctx.strokeRect(a.x,a.y,1,1);}
 for(const t of trees){const s=screen(t.x,t.y);ellipse(s.x,s.y+3,t.size*.78,t.size*.34,'rgba(15,35,27,.28)');ellipse(s.x,s.y-t.size*.2,t.size*.56,t.size*.72,'#375f49');ellipse(s.x-3,s.y-t.size*.48,t.size*.42,t.size*.57,'#6d9567');ellipse(s.x+3,s.y-t.size*.35,t.size*.35,t.size*.5,'#527d58')}
 for(const l of lamps){let s=screen(l.x,l.y);ctx.strokeStyle='#46504a';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(s.x,s.y);ctx.lineTo(s.x,s.y-19);ctx.lineTo(s.x+5,s.y-22);ctx.stroke();ellipse(s.x+5,s.y-22,2,2,'#f8db97')}
}
function drawBuildings(){for(const b of buildings){let pts=[[b.x,b.y],[b.x+b.w,b.y],[b.x+b.w,b.y+b.h],[b.x,b.y+b.h]].map(p=>screen(...p));let h=b.height,top=pts.map(p=>({x:p.x,y:p.y-h}));
 // shadow and facade faces
 poly(pts.map(p=>({x:p.x+9,y:p.y+5})), 'rgba(19,31,26,.24)');poly([pts[1],pts[2],top[2],top[1]],shade(b.color,-28));poly([pts[2],pts[3],top[3],top[2]],shade(b.color,-15));poly(top,b.color,'rgba(218,215,179,.26)',1);
 if(b.type==='tower'){for(let i=0;i<3;i++){let t=(i+1)/4;let p1={x:top[0].x+(top[1].x-top[0].x)*t,y:top[0].y+(top[1].y-top[0].y)*t};let p2={x:top[3].x+(top[2].x-top[3].x)*t,y:top[3].y+(top[2].y-top[3].y)*t};ctx.strokeStyle='rgba(233,217,163,.25)';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(p1.x,p1.y);ctx.lineTo(p2.x,p2.y);ctx.stroke()}}
 // windows on front-facing sides
 if(b.type!=='warehouse'){for(let row=0;row<Math.min(7,Math.floor(h/13));row++)for(let col=0;col<Math.max(1,Math.floor(b.w/24));col++){let u=(col+1)/(Math.floor(b.w/24)+1),v=(row+1)/(Math.min(7,Math.floor(h/13))+1);let wx=pts[3].x+(pts[2].x-pts[3].x)*u,wy=pts[3].y+(pts[2].y-pts[3].y)*u-h*v;ctx.fillStyle=(day<6||day>19)&&rand(b.seed,row,col)>.45?'#ffd38b':'rgba(220,207,157,.49)';ctx.fillRect(wx-2,wy-2,4,5)}}
 if(b.type==='shop'||b.type==='warehouse'){let mid={x:(pts[0].x+pts[3].x)/2,y:(pts[0].y+pts[3].y)/2-h*.27};ctx.fillStyle=b.type==='shop'?'#edb974':'#6e7770';ctx.fillRect(mid.x-8,mid.y-6,16,12);if(b.type==='shop'){ctx.fillStyle='#ffcf80';ctx.fillRect(mid.x-9,mid.y-11,18,4)}}
 }}
function shade(hex,delta){let n=parseInt(hex.slice(1),16),r=Math.max(0,Math.min(255,(n>>16)+delta)),g=Math.max(0,Math.min(255,((n>>8)&255)+delta)),b=Math.max(0,Math.min(255,(n&255)+delta));return`rgb(${r},${g},${b})`}

