function updateHud(){ui.health.textContent=Math.round(player.health);ui.healthBar.style.width=player.health+'%';ui.cash.textContent='$'+player.cash.toLocaleString();ui.district.textContent=districtAt((player.vehicle||player).x,(player.vehicle||player).y);ui.stars.textContent=Array.from({length:5},(_,i)=>i<wanted?'★':'☆').join(' ');let h=Math.floor(day),m=Math.floor((day-h)*60);ui.clock.textContent=String(h).padStart(2,'0')+':'+String(m).padStart(2,'0');ui.weatherIcon.textContent=day>19||day<6?'☾':'☀';ui.weather.textContent=day>19||day<6?'NIGHT':'CLEAR'}
function drawMinimap(){let w=mini.width,h=mini.height,sx=w/W,sy=h/W;mx.clearRect(0,0,w,h);mx.fillStyle='#748b70';mx.fillRect(0,0,w,h);mx.fillStyle='#487c83';mx.beginPath();mx.moveTo(1900*sx,0);mx.lineTo(w,0);mx.lineTo(w,h);mx.lineTo(2210*sx,h);mx.lineTo(2140*sx,1900*sy);mx.lineTo(2040*sx,1760*sy);mx.fill();mx.fillStyle='#4b5150';for(let k=0;k<=W;k+=CELL){mx.fillRect(k*sx,0,ROAD*sx,h);mx.fillRect(0,k*sy,w,ROAD*sy)}mx.fillStyle='rgba(65,81,69,.9)';for(const b of buildings)mx.fillRect(b.x*sx,b.y*sy,b.w*sx,b.h*sy);const t=player.vehicle||player;if(objective.active){mx.fillStyle='#ffd786';mx.beginPath();mx.arc(objective.x*sx,objective.y*sy,3,0,Math.PI*2);mx.fill()}for(const c of cars)if(c.type==='police'){mx.fillStyle='#f06e65';mx.fillRect(c.x*sx-2,c.y*sy-2,4,4)}mx.fillStyle='#b9f4d2';mx.strokeStyle='#173b35';mx.lineWidth=1.5;mx.beginPath();mx.arc(t.x*sx,t.y*sy,4,0,Math.PI*2);mx.fill();mx.stroke()}
function frame(t){let dt=Math.min(.04,(t-last)/1000||0);last=t;update(dt);draw();requestAnimationFrame(frame)}
function setKey(name,on){touch[name]=on}
addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' ','Shift'].includes(e.key))e.preventDefault();keys[e.key===' '?'Space':e.key]=true;if(e.repeat)return;if(e.key.toLowerCase()==='e')action();if(e.key===' '||e.key==='Space')fireShot();if(e.key.toLowerCase()==='h')document.getElementById('help').classList.toggle('open')});
addEventListener('keyup',e=>{keys[e.key===' '?'Space':e.key]=false});
document.getElementById('start').addEventListener('click',()=>{gameStarted=true;ui.intro.style.display='none';toast('WELCOME TO SAN PALOMA');document.getElementById('help').classList.add('open')});
document.getElementById('close-help').addEventListener('click',()=>document.getElementById('help').classList.remove('open'));
document.getElementById('map-toggle').addEventListener('click',()=>{document.querySelector('.minimap-frame').classList.toggle('hidden')});
for(const btn of document.querySelectorAll('[data-key]')){const dir=btn.dataset.key, map={up:'up',down:'down',left:'left',right:'right'};const on=e=>{e.preventDefault();setKey(map[dir],true)};const off=e=>{e.preventDefault();setKey(map[dir],false)};btn.addEventListener('pointerdown',on);['pointerup','pointercancel','pointerleave'].forEach(ev=>btn.addEventListener(ev,off))}
for(const btn of document.querySelectorAll('[data-action]'))btn.addEventListener('pointerdown',e=>{e.preventDefault();btn.dataset.action==='enter'?action():fireShot()});
updateHud();requestAnimationFrame(frame);
})();

