15: function createCity(){
16:  for(let gy=0;gy<8;gy++)for(let gx=0;gx<8;gx++){
17:   const b=blockBounds(gx*CELL+ROAD,gy*CELL+ROAD),r=rand(gx,gy),district=districtAt(b.x,b.y);
18:   if(r<.14||((gx===3||gx===4)&&(gy===3||gy===4))){parks.push({...b,kind:r<.06?'plaza':'park',seed:gx*19+gy});for(let i=0;i<5;i++)trees.push({x:b.x+25+rand(gx,gy,i)*Math.max(1,b.w-50),y:b.y+25+rand(gy,gx,i+7)*Math.max(1,b.h-50),size:11+rand(gx,gy,i+13)*7});continue}
19:   const count=district==='MIRAGE DOWNTOWN'?3:1+Math.floor(rand(gx,gy,2)*2);
